using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using NhaTro.Domain.Entities;

namespace NhaTro.Infrastructure.Persistence.Configurations;

// Ids are generated by the domain (Guid.NewGuid), so EF must treat entities discovered through navigations as new (Added), not existing.

public class UserConfiguration : IEntityTypeConfiguration<User>
{
    public void Configure(EntityTypeBuilder<User> b)
    {
        b.Property(x => x.Id).ValueGeneratedNever();
        b.Property(x => x.Email).HasMaxLength(256).IsRequired(false);
        b.Property(x => x.Phone).HasMaxLength(30);
        b.Property(x => x.FullName).HasMaxLength(200);
        b.Property(x => x.CreatedAt).HasDefaultValueSql("SYSDATETIMEOFFSET()");
        b.HasIndex(x => x.Email).IsUnique().HasFilter("[Email] IS NOT NULL");
        b.HasIndex(x => x.Phone).IsUnique().HasFilter("[Phone] IS NOT NULL");
        b.HasOne<User>().WithMany().HasForeignKey(x => x.EmployerId).OnDelete(DeleteBehavior.NoAction);
    }
}

public class PropertyConfiguration : IEntityTypeConfiguration<Property>
{
    public void Configure(EntityTypeBuilder<Property> b)
    {
        b.Property(x => x.Id).ValueGeneratedNever();
        b.Property(x => x.Name).HasMaxLength(200);
        b.Property(x => x.Address).HasMaxLength(500);
        b.Property(x => x.BankName).HasMaxLength(100).HasDefaultValue("");
        b.Property(x => x.BankAccountNumber).HasMaxLength(50).HasDefaultValue("");
        b.Property(x => x.BankAccountName).HasMaxLength(200).HasDefaultValue("");
        b.Property(x => x.QrContentType).HasMaxLength(30).HasDefaultValue("");
        b.Property(x => x.ServiceAmountPerMonth).HasDefaultValue(0m);
        b.HasOne<User>().WithMany().HasForeignKey(x => x.OwnerId);   // aggregates reference each other by id only
        b.HasIndex(x => x.OwnerId);
    }
}

public class RoomConfiguration : IEntityTypeConfiguration<Room>
{
    public void Configure(EntityTypeBuilder<Room> b)
    {
        b.Property(x => x.Id).ValueGeneratedNever();
        b.Property(x => x.Name).HasMaxLength(100);
        b.Property(x => x.ReservedTenantName).HasMaxLength(200);
        b.Property(x => x.ReservedPhone).HasMaxLength(30);
        b.Property(x => x.OccupantCount).HasDefaultValue(1);
        b.Property(x => x.WaterByOccupant).HasDefaultValue(false);
        b.Property(x => x.ServiceAmount).HasDefaultValue(0m);
        b.HasOne<Property>().WithMany().HasForeignKey(x => x.PropertyId);
        b.HasIndex(x => new { x.PropertyId, x.Name }).IsUnique();
        b.HasMany(x => x.Tenancies).WithOne().HasForeignKey(t => t.RoomId).OnDelete(DeleteBehavior.Cascade);
        b.Navigation(x => x.Tenancies).UsePropertyAccessMode(PropertyAccessMode.Field);
    }
}

public class TenancyConfiguration : IEntityTypeConfiguration<Tenancy>
{
    public void Configure(EntityTypeBuilder<Tenancy> b)
    {
        b.Property(x => x.Id).ValueGeneratedNever();
        b.Property(x => x.TenantName).HasMaxLength(200);
        b.Property(x => x.Phone).HasMaxLength(30);
        b.Property(x => x.IdentityNumber).HasMaxLength(30);
        b.Property(x => x.Gender).HasMaxLength(10);
        b.Property(x => x.Address).HasMaxLength(500);
        b.Property(x => x.Notes).HasMaxLength(2000);
        b.Property(x => x.TemporaryResidenceRegistered).HasDefaultValue(false);
        // at most one active tenancy per room
        b.HasIndex(x => x.RoomId).IsUnique().HasFilter("[EndDate] IS NULL");
    }
}

public class InvoiceConfiguration : IEntityTypeConfiguration<Invoice>
{
    public void Configure(EntityTypeBuilder<Invoice> b)
    {
        b.Property(x => x.Id).ValueGeneratedNever();
        b.Property(x => x.Month).HasMaxLength(7);
        b.Property(x => x.TenantName).HasMaxLength(200);
        b.Property(x => x.Gender).HasMaxLength(10);
        b.Property(x => x.ServiceAmount).HasDefaultValue(0m);
        b.Property(x => x.WaterByOccupant).HasDefaultValue(false);
        b.Property(x => x.OccupantCount).HasDefaultValue(1);
        b.Property(x => x.WaterRatePerPerson).HasDefaultValue(0m);
        b.Property(x => x.ElectricRate).HasDefaultValue(0m);
        b.Property(x => x.OtherNote).HasMaxLength(200);
        b.HasOne<Room>().WithMany().HasForeignKey(x => x.RoomId).OnDelete(DeleteBehavior.Cascade);
        b.HasIndex(x => new { x.RoomId, x.Month }).IsUnique();
    }
}

public class DepositReceiptConfiguration : IEntityTypeConfiguration<DepositReceipt>
{
    public void Configure(EntityTypeBuilder<DepositReceipt> b)
    {
        b.Property(x => x.Id).ValueGeneratedNever();
        b.Property(x => x.TenantName).HasMaxLength(200);
        b.Property(x => x.Phone).HasMaxLength(30);
        b.HasOne<Room>().WithMany().HasForeignKey(x => x.RoomId).OnDelete(DeleteBehavior.Cascade);
        b.HasIndex(x => new { x.RoomId, x.ReceivedAt });
    }
}

public class FinancialExpenseConfiguration : IEntityTypeConfiguration<FinancialExpense>
{
    public void Configure(EntityTypeBuilder<FinancialExpense> b)
    {
        b.Property(x => x.Id).ValueGeneratedNever();
        b.Property(x => x.Category).HasMaxLength(20);
        b.Property(x => x.Description).HasMaxLength(200);
        b.Property(x => x.Recipient).HasMaxLength(200);
        b.HasOne<User>().WithMany().HasForeignKey(x => x.OwnerId).OnDelete(DeleteBehavior.NoAction);
        b.HasOne<Property>().WithMany().HasForeignKey(x => x.PropertyId).OnDelete(DeleteBehavior.SetNull);
        b.HasIndex(x => new { x.OwnerId, x.Date });
    }
}

public class StaffAssignmentConfiguration : IEntityTypeConfiguration<StaffAssignment>
{
    public void Configure(EntityTypeBuilder<StaffAssignment> b)
    {
        b.Property(x => x.Id).ValueGeneratedNever();
        b.HasIndex(x => new { x.UserId, x.PropertyId }).IsUnique();
        b.HasOne<User>().WithMany().HasForeignKey(x => x.UserId).OnDelete(DeleteBehavior.NoAction);
        b.HasOne<Property>().WithMany().HasForeignKey(x => x.PropertyId).OnDelete(DeleteBehavior.Cascade);
    }
}

public class EmployeePagePermissionConfiguration : IEntityTypeConfiguration<EmployeePagePermission>
{
    public void Configure(EntityTypeBuilder<EmployeePagePermission> b)
    {
        b.Property(x => x.Id).ValueGeneratedNever();
        b.Property(x => x.Page).HasMaxLength(30);
        b.HasIndex(x => new { x.UserId, x.Page }).IsUnique();
        b.HasOne<User>().WithMany().HasForeignKey(x => x.UserId).OnDelete(DeleteBehavior.Cascade);
    }
}

public class RoomImageConfiguration : IEntityTypeConfiguration<RoomImage>
{
    public void Configure(EntityTypeBuilder<RoomImage> b)
    {
        b.Property(x => x.Id).ValueGeneratedNever();
        b.Property(x => x.Caption).HasMaxLength(200);
        b.Property(x => x.ContentType).HasMaxLength(30);
        b.HasOne<Room>().WithMany().HasForeignKey(x => x.RoomId).OnDelete(DeleteBehavior.Cascade);
    }
}

public class OccupantConfiguration : IEntityTypeConfiguration<Occupant>
{
    public void Configure(EntityTypeBuilder<Occupant> b)
    {
        b.Property(x => x.Id).ValueGeneratedNever();
        b.Property(x => x.Name).HasMaxLength(200);
        b.Property(x => x.Phone).HasMaxLength(30);
        b.Property(x => x.IdentityNumber).HasMaxLength(30);
        b.Property(x => x.Gender).HasMaxLength(10);
        b.Property(x => x.Address).HasMaxLength(500);
        b.Property(x => x.Notes).HasMaxLength(2000);
        b.HasOne<Room>().WithMany().HasForeignKey(x => x.RoomId).OnDelete(DeleteBehavior.Cascade);
